// Tudo chega como texto (o app manda formulário simples); listas vêm em JSON.
const corpo = $('Recebe pedido do app').first().json.body || {};
const texto = (v) => String(v ?? '').trim();
const id = (v) => (/^rec[A-Za-z0-9]{14}$/.test(texto(v)) ? texto(v) : '');
const lerLista = (v) => {
  try { const l = JSON.parse(texto(v) || '[]'); return Array.isArray(l) ? l.map(texto).filter(Boolean) : null; }
  catch (e) { return null; }
};

const ACOES = ['listar', 'salvar', 'excluir', 'excluirEmpresa', 'vincularCliente', 'desvincularCliente'];
const acao = ACOES.includes(texto(corpo.acao)) ? texto(corpo.acao) : '';
const contatoId = id(corpo.id);
// vincularCliente / desvincularCliente: o cliente que ganha ou perde este contato.
const clienteId = id(corpo.clienteId);
const nome = texto(corpo.nome).replace(/\s+/g, ' ').slice(0, 120);
const funcao = texto(corpo.funcao).replace(/\s+/g, ' ').slice(0, 60);
// excluirEmpresa: o nome que sai de todos os contatos que o têm.
const empresa = texto(corpo.empresa).replace(/\s+/g, ' ').slice(0, 120);
// Empresas = onde a pessoa trabalha (nomes, lista em JSON), NÃO os clientes. Os clientes de
// quem a pessoa é contato são cuidados pelo Cadastro de clientes e aqui não mudam.
// empresaIds / empresaId (clientes) é o formato das versões 2026.10.27a/b do app, aceito
// enquanto algum aparelho ainda estiver com elas.
const modoAntigo = corpo.empresas === undefined;
const nomesBrutos = modoAntigo ? [] : lerLista(corpo.empresas);
const empresasNomes = [];
for (const n of (nomesBrutos || []).map((v) => v.replace(/\s+/g, ' ').slice(0, 120))) {
  if (!empresasNomes.some((x) => x.toLowerCase() === n.toLowerCase())) empresasNomes.push(n);
}
const empresasBrutas = texto(corpo.empresaIds) ? lerLista(corpo.empresaIds) : (texto(corpo.empresaId) ? [texto(corpo.empresaId)] : []);
const empresaIds = [...new Set((empresasBrutas || []).map(id))];
const observacoes = texto(corpo.observacoes).slice(0, 2000);
const telefonesBrutos = lerLista(corpo.telefones);
const emailsBrutos = lerLista(corpo.emails);

// Telefone fica só com os dígitos (o app já manda com o 55 quando o número
// está completo; incompleto vai como está, porque o app já avisou).
const telefones = [...new Set((telefonesBrutos || []).map((t) => t.replace(/\D/g, '')).filter(Boolean))];
// E-mail repetido com outra caixa (Fulano@ e fulano@) é o mesmo e-mail.
const emails = [];
for (const e of emailsBrutos || []) if (!emails.some((x) => x.toLowerCase() === e.toLowerCase())) emails.push(e);

let erro = '';
if (!acao) erro = 'Ação inválida.';
else if (acao === 'excluir' && !contatoId) erro = 'Contato inválido.';
else if (acao === 'excluirEmpresa' && !empresa) erro = 'Empresa inválida.';
else if ((acao === 'vincularCliente' || acao === 'desvincularCliente') && !contatoId) erro = 'Contato inválido.';
else if ((acao === 'vincularCliente' || acao === 'desvincularCliente') && !clienteId) erro = 'Cliente inválido.';
else if (acao === 'salvar') {
  if (texto(corpo.id) && !contatoId) erro = 'Contato inválido.';
  else if (!nome) erro = 'Escreva o nome do contato.';
  else if (!telefonesBrutos || !emailsBrutos) erro = 'Telefone ou e-mail em formato inválido.';
  else if (modoAntigo && (!empresasBrutas || empresaIds.includes('') || empresaIds.length > 50)) erro = 'Empresa inválida.';
  else if (!modoAntigo && (!nomesBrutos || empresasNomes.length > 20)) erro = 'Empresa inválida.';
  else if (telefones.length > 10 || telefones.some((t) => t.length > 15)) erro = 'Telefone inválido.';
  else if (emails.length > 20 || emails.some((e) => e.length > 254)) erro = 'E-mail inválido.';
}

return [{ json: { acao, contatoId, clienteId, nome, funcao, empresa, modoAntigo, empresaIds: empresaIds.filter(Boolean), empresasNomes, observacoes, telefones, emails, erro } }];

const e = $('Le entrada').first().json;
const empresasBrutas = $('Busca empresas').all().map((i) => i.json);
const contatosBrutos = $('Busca contatos').all().map((i) => i.json);
const recusa = (mensagem) => [{ json: { gravar: false, resposta: { ok: false, mensagem } } }];

// Banco fora do ar não pode parecer "nenhum contato".
if (empresasBrutas.some((j) => j && j.error) || contatosBrutos.some((j) => j && j.error)) {
  return recusa('Não foi possível falar com o banco agora. Tente de novo em instantes.');
}

const QUEBRA = String.fromCharCode(10);
const porLinha = (t) => String(t || '').split(QUEBRA).map((v) => v.trim()).filter(Boolean);
const empresas = empresasBrutas.filter((j) => j && j.id).map((j) => {
  const f = j.fields || {};
  return { id: j.id, razaoSocial: f.Razao_Social_Nome || '', nomeFantasia: f.Nome_Fantasia_Identificador || '', status: f.Status || '', emailsFin: f.Emails_Financeiro_NFE || '' };
});
const contatos = contatosBrutos.filter((j) => j && j.id).map((j) => {
  const f = j.fields || {};
  return {
    id: j.id, nome: f.Nome_Contato || '', funcao: f.Cargo_Funcao || '',
    telefones: porLinha(f.WhatsApps), emails: porLinha(f.Emails),
    empresas: porLinha(f.Empresas), clienteIds: f.Entidades_Vinculadas || [],
    // empresaIds = clientes, com o nome antigo, para as versões 2026.10.27a/b do app
    empresaIds: f.Entidades_Vinculadas || [], observacoes: f.Observacoes || '', status: f.Status || '',
  };
});

if (e.acao === 'listar') {
  contatos.sort((a, b) => (a.nome || '~').localeCompare(b.nome || '~', 'pt-BR'));
  // "clientes" é a lista de clientes; "empresas" é a mesma lista com o nome antigo (versões 27a/b).
  return [{ json: { gravar: false, resposta: { ok: true, contatos, clientes: empresas, empresas } } }];
}

const atual = e.contatoId ? contatos.find((c) => c.id === e.contatoId) : null;
if (e.contatoId && !atual) return recusa('Esse contato não existe mais (pode ter sido excluído). Toque em Atualizar.');

const url = 'http://127.0.0.1:5690/v0/app6PyYmtFduIMp7B/tblXXOEOCwQnC2qFX';
// Junta listas de e-mails sem repetir (Fulano@ e fulano@ são o mesmo), na ordem em que vieram.
const juntarEmails = (...grupos) => {
  const saida = [];
  for (const g of grupos) for (const bruto of g) {
    const v = String(bruto ?? '').trim();
    if (v && !saida.some((x) => x.toLowerCase() === v.toLowerCase())) saida.push(v);
  }
  return saida;
};
const separarEmails = (t) => String(t || '').split(/[\n,;]+/);
// Regra do dono (30/10/2026): os e-mails do contato entram sempre também no campo do
// financeiro dos clientes dele. Só soma, nunca tira; cliente que já tem todos fica de fora.
const urlClientes = 'http://127.0.0.1:5690/v0/app6PyYmtFduIMp7B/tbl5Joji6gAir3mNh';
const somarNosClientes = (emails, clienteIds) => {
  const registros = [];
  for (const cliente of empresas.filter((x) => clienteIds.includes(x.id))) {
    const atuais = juntarEmails(separarEmails(cliente.emailsFin));
    const juntos = juntarEmails(atuais, emails);
    if (juntos.length > atuais.length) registros.push({ id: cliente.id, fields: { Emails_Financeiro_NFE: juntos.join(QUEBRA) } });
  }
  const itens = [];
  for (let i = 0; i < registros.length; i += 10) {
    itens.push({ json: { gravar: true, acao: 'emailsDosClientes', metodo: 'PATCH', url: urlClientes, corpo: { records: registros.slice(i, i + 10) } } });
  }
  return itens;
};
if (e.acao === 'excluir') {
  return [{ json: { gravar: true, acao: 'excluir', contatoId: e.contatoId, metodo: 'DELETE', url: url + '/' + e.contatoId, corpo: {} } }];
}

// Excluir uma empresa = tirar o nome dela de todos os contatos que o têm, mexendo só no campo
// Empresas. Grafias que só mudam acento, maiúscula ou pontuação ("Acme Ltda." e "ACME LTDA")
// são a mesma, igual às sugestões do app (normalizarTexto).
if (e.acao === 'excluirEmpresa') {
  const chave = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
  const alvo = chave(e.empresa);
  if (!alvo) return recusa('Empresa inválida.');
  const registros = contatos.filter((c) => c.empresas.some((n) => chave(n) === alvo))
    .map((c) => ({ id: c.id, fields: { Empresas: c.empresas.filter((n) => chave(n) !== alvo).join(QUEBRA) } }));
  // Nenhum contato tem mais esse nome (outro aparelho já tirou): já está feito.
  if (!registros.length) return [{ json: { gravar: false, resposta: { ok: true, contatos: [] } } }];
  return [{ json: { gravar: true, acao: 'excluirEmpresa', metodo: 'PATCH', url, corpo: { records: registros } } }];
}

// Ligar um contato salvo a um cliente (ou tirar dele), pela tela do cliente. Mexe só em
// Entidades_Vinculadas: tirar nunca apaga o contato, que continua no Cadastro de contatos.
if (e.acao === 'vincularCliente' || e.acao === 'desvincularCliente') {
  if (e.acao === 'vincularCliente' && !empresas.some((x) => x.id === e.clienteId)) {
    return recusa('Esse cliente não está mais no cadastro. Toque em Atualizar.');
  }
  const vinculos = atual.clienteIds.filter((x) => x !== e.clienteId);
  if (e.acao === 'vincularCliente') vinculos.push(e.clienteId);
  // O pedido do contato vai primeiro: é a resposta dele que volta para o app.
  const doCliente = e.acao === 'vincularCliente' ? somarNosClientes(atual.emails, [e.clienteId]) : [];
  return [{ json: { gravar: true, acao: e.acao, metodo: 'PATCH', url, corpo: { records: [{ id: atual.id, fields: { Entidades_Vinculadas: vinculos } }] } } }, ...doCliente];
}

if (e.modoAntigo && e.empresaIds.some((idEmpresa) => !empresas.some((x) => x.id === idEmpresa))) {
  return recusa('Essa empresa não está mais no cadastro. Toque em Atualizar e escolha de novo.');
}

const campos = {
  Nome_Contato: e.nome,
  Cargo_Funcao: e.funcao || null,
  WhatsApps: e.telefones.join(QUEBRA),
  Emails: e.emails.join(QUEBRA),
  Observacoes: e.observacoes,
};
if (e.modoAntigo) campos.Entidades_Vinculadas = e.empresaIds;
else campos.Empresas = e.empresasNomes.join(QUEBRA);
if (!atual) campos.Status = 'Ativo';
const registro = atual ? { id: atual.id, fields: campos } : { fields: campos };
const clientesDoContato = e.modoAntigo ? e.empresaIds : (atual ? atual.clienteIds : []);
return [{ json: { gravar: true, acao: 'salvar', metodo: atual ? 'PATCH' : 'POST', url, corpo: { typecast: true, records: [registro] } } },
  ...somarNosClientes(e.emails, clientesDoContato)];

const d = $('Decide').first().json;
if (d.acao === 'excluir') return [{ json: { ok: true, excluido: d.contatoId } }];
const QUEBRA = String.fromCharCode(10);
const porLinha = (t) => String(t || '').split(QUEBRA).map((v) => v.trim()).filter(Boolean);
const paraApp = (reg) => {
  const f = reg.fields || {};
  return {
    id: reg.id, nome: f.Nome_Contato || '', funcao: f.Cargo_Funcao || '',
    telefones: porLinha(f.WhatsApps), emails: porLinha(f.Emails),
    empresas: porLinha(f.Empresas), clienteIds: f.Entidades_Vinculadas || [],
    empresaIds: f.Entidades_Vinculadas || [], observacoes: f.Observacoes || '', status: f.Status || '',
  };
};
const regs = ($input.first().json.records || []).filter((r) => r && r.id);
const falha = [{ json: { ok: false, mensagem: 'Não foi possível salvar agora. Tente de novo em instantes.' } }];
// excluirEmpresa: devolve os contatos que perderam o nome, já como ficaram.
if (d.acao === 'excluirEmpresa') return regs.length === d.corpo.records.length ? [{ json: { ok: true, contatos: regs.map(paraApp) } }] : falha;
if (!regs[0]) return falha;
return [{ json: { ok: true, contato: paraApp(regs[0]) } }];
